const item = $input.item.json || {};
const leadData = item.data || item.lead_data || item.body?.lead_data || item.body || item;

// Extrai campos do Lead Ads ou Webhook
const rawName = leadData['Nome completo'] || leadData['full_name'] || leadData['name'] || leadData['nome'] || leadData['Nome'] || 'Lead Meta Ads';
const rawPhone = leadData['Telefone'] || leadData['phone_number'] || leadData['phone'] || leadData['telefone'] || leadData['WhatsApp'] || '';
const email = leadData['Email'] || leadData['email'] || leadData['E-mail'] || '';

// Sanitiza telefone para padrão brasileiro (55 + DDD + 9 dígitos)
let phone = String(rawPhone).replace(/\D/g, '');
if (phone && !phone.startsWith('55') && phone.length <= 11) {
  phone = '55' + phone;
}

// Mapeia perguntas de ambientes
const rooms = [];
if (leadData['Qual ambiente deseja planejar?']) rooms.push(leadData['Qual ambiente deseja planejar?']);
if (leadData['Ambientes']) rooms.push(leadData['Ambientes']);
if (leadData['Qual é o seu objetivo principal hoje?']) rooms.push(leadData['Qual é o seu objetivo principal hoje?']);

const utmCampaign = leadData['campaign_name'] || item.campaign_name || 'Campanha Meta Ads';

return {
  json: {
    name: String(rawName).trim(),
    phone,
    email: String(email).trim(),
    stage: 'entrada',
    value: 0,
    utmSource: 'Facebook Ads',
    utmCampaign,
    rooms
  }
};
